import { site } from "@/lib/site";
import { buildRssXml } from "@/lib/discovery";
import { getPublishedPosts } from "@/lib/blog";

export async function GET() {
  const xml = buildRssXml({
    siteUrl: site.url,
    siteName: site.name,
    description: site.description,
    posts: getPublishedPosts(),
    feedPath: site.rssPath,
  });

  return new Response(xml, {
    headers: {
      "Content-Type": "application/rss+xml; charset=utf-8",
      "Cache-Control": "s-maxage=600, stale-while-revalidate",
    },
  });
}
import type { PostRecord } from "./blog";

export type RssInput = {
  siteUrl: string;
  siteName: string;
  description: string;
  posts: readonly PostRecord[];
  /** The feed's own address, so it can point at itself. */
  feedPath: string;
  /** Injected so the output is a pure function of its input, and testable. */
  now?: Date;
};

export type SitemapEntry = {
  url: string;
  lastModified: string;
};

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

/**
 * RSS 2.0, with the three declarations readers actually use and that a
 * hand-rolled feed usually forgets.
 *
 * `atom:link rel="self"` is the feed's own address: a reader that has been
 * handed the file by any other route — a proxy, a mirror, a copy-paste —
 * learns where to poll from here. `lastBuildDate` is what lets a reader ask
 * "has anything changed?" without downloading the whole feed. `language` is
 * what tells it not to run the titles through a translator.
 *
 * The feed carries summaries, not whole articles. That is a choice: the posts
 * are MDX with components in them, and a feed that ships half-rendered markup
 * is worse than one that ships a paragraph and a link.
 */
export function buildRssXml({
  siteUrl,
  siteName,
  description,
  posts,
  feedPath,
  now = new Date(),
}: RssInput): string {
  const ordered = posts
    .slice()
    .sort(
      (a, b) =>
        new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
    );

  const items = ordered
    .map((post) => {
      const url = `${siteUrl}/blog/${encodeURIComponent(post.slug)}`;
      return `    <item>
      <title>${escapeXml(post.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <description>${escapeXml(post.summary)}</description>
      <pubDate>${new Date(post.publishedAt).toUTCString()}</pubDate>
    </item>`;
    })
    .join("\n");

  // The newest post if there is one, otherwise the moment the feed was built:
  // a `lastBuildDate` that moves on every request would make every poll look
  // like news.
  const lastBuild = ordered[0]
    ? new Date(ordered[0].publishedAt)
    : now;

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(siteName)}</title>
    <link>${escapeXml(siteUrl)}</link>
    <description>${escapeXml(description)}</description>
    <language>en</language>
    <lastBuildDate>${lastBuild.toUTCString()}</lastBuildDate>
    <atom:link href="${escapeXml(`${siteUrl}${feedPath}`)}" rel="self" type="application/rss+xml" />
${items ? `${items}\n` : ""}  </channel>
</rss>`;
}

export function buildSitemapEntries({
  siteUrl,
  posts,
}: {
  siteUrl: string;
  posts: readonly PostRecord[];
}): SitemapEntry[] {
  const today = new Date().toISOString().slice(0, 10);
  // `/blog` 404s until a Post is published; `/projects` is always a page.
  const routes = posts.length > 0 ? ["", "/projects", "/blog"] : ["", "/projects"];
  const core = routes.map((route) => ({
    url: `${siteUrl}${route}`,
    lastModified: today,
  }));

  const postEntries = posts.map((post) => ({
    url: `${siteUrl}/blog/${encodeURIComponent(post.slug)}`,
    lastModified: post.publishedAt,
  }));

  return [...core, ...postEntries];
}

export function ogImagePath(title: string): string {
  return `/og?title=${encodeURIComponent(title)}`;
}
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { Panel, PanelHeader, PanelTitle, PanelTitleSup } from "@/components/panel";
import { PostSearch } from "@/components/post-search";
import { getPublishedPosts } from "@/lib/blog";
import { serializeJsonLd } from "@/lib/json-ld";
import { site } from "@/lib/site";

/**
 * With nothing published the route 404s, so it must not advertise itself as a
 * Blog — naming a page the Visitor cannot reach is a lie told by the tab.
 */
export function generateMetadata(): Metadata {
  if (getPublishedPosts().length === 0) return { title: "Nothing lives here" };
  return {
    title: "Blog",
    alternates: { canonical: `${site.url}/blog` },
  };
}

export default function BlogPage() {
  // Nothing empty is ever shown to a Visitor (CONTEXT.md → Blog / Post).
  const posts = getPublishedPosts();
  if (posts.length === 0) notFound();

  // The body is the one thing a row never draws, and the rows are drawn in the
  // browser here — so it is dropped before the list crosses over rather than
  // shipped down and ignored.
  const summaries = posts.map(({ content: _content, ...summary }) => summary);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "Blog",
    "@id": `${site.url}/blog`,
    name: "Blog",
    url: `${site.url}/blog`,
    author: { "@type": "Person", name: site.name, url: site.url },
    blogPost: posts.map((post) => ({
      "@type": "BlogPosting",
      "@id": `${site.url}/blog/${post.slug}`,
      headline: post.title,
      description: post.summary,
      url: `${site.url}/blog/${post.slug}`,
      datePublished: post.publishedAt,
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
      />

      {/* One panel, not a heading floating above a list: the index is a single
          thing on the page, and the site draws single things inside rails.
          There is no tagline under the title — the reference needs one because
          its heading *is* the tagline; ours says the word the nav promised and
          then gets out of the way of the posts. */}
      <Panel id="blog">
        <PanelHeader>
          <PanelTitle as="h1">
            Blog
            <PanelTitleSup className="tabular-nums">
              {posts.length}
            </PanelTitleSup>
          </PanelTitle>
        </PanelHeader>

        <PostSearch posts={summaries} />
      </Panel>
    </>
  );
}
import { Rss, SOCIAL_ICONS } from "@/components/icons";
import { SiteWordmark } from "@/components/site-wordmark";
import { site } from "@/lib/site";

/**
 * The profiles, minus the mailbox.
 *
 * The overview's "say hi" row is the directory — it is the place that answers
 * "how do I reach this person", so it carries every way, email included. The
 * footer is a signature, and a signature does not repeat the directory: it
 * carries the three places the work lives, and the feed, which is a property
 * of the site rather than of the person and so belongs here and nowhere else.
 */
const FOOTER_SOCIALS = site.socials.filter(
  (social) => !social.href.startsWith("mailto:"),
);

export function SiteFooter() {
  return (
    <footer className="max-w-screen overflow-x-clip px-2">
      <div className="mx-auto border-x border-line md:max-w-3xl">
        <div className="screen-line-top screen-line-bottom">
          <div className="stripe-divider h-12" />
        </div>

        {/* One closing line: the copyright reads left, the glyphs read right,
            and on a phone they stack centred rather than squeezing. */}
        <div className="screen-line-top screen-line-bottom flex flex-col items-center justify-center gap-x-4 gap-y-3 px-4 py-3 text-sm text-muted-foreground sm:flex-row sm:justify-between">
          {/* The mark, not the legal name: the wordmark below signs the page
              and this line should agree with it. */}
          <span>
            &copy; {new Date().getFullYear()} {site.handle.toLowerCase()}.
          </span>

          {/* Four glyphs on one gutter. The rules that used to stand between
              them were 16px of hairline at 12px intervals — texture, at this
              size, not structure. */}
          <nav aria-label="Elsewhere" className="flex items-center gap-4">
            {FOOTER_SOCIALS.map((social) => {
              const Glyph = SOCIAL_ICONS[social.label];
              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.label}
                  title={social.label}
                  className="flex items-center transition-colors hover:text-foreground"
                >
                  <Glyph className="size-4" />
                </a>
              );
            })}
            <a
              href={site.rssPath}
              aria-label="RSS feed"
              title="RSS feed — paste this address into a feed reader"
              className="flex items-center transition-colors hover:text-foreground"
            >
              <Rss className="size-4" />
            </a>
          </nav>
        </div>

      </div>

      <SiteWordmark text={site.handle.toLowerCase()} className="text-foreground" />

      <div aria-hidden className="h-(--fade-bottom-height)" />

      <div className="pb-[env(safe-area-inset-bottom,0)]" />
    </footer>
  );
}

